def countRepeatedFragments(s, L):
    code = {'A': 0, 'C': 1, 'G': 2, 'T': 3}
    mask = (1 << (2 * L)) - 1
    seen = set()
    repeated = set()
    h = 0
    for i, ch in enumerate(s):
        h = ((h << 2) | code[ch]) & mask
        if i >= L - 1:
            if h in seen:
                repeated.add(h)
            else:
                seen.add(h)
    return len(repeated)
